{"actions":[{"tool":"write_file","path":"core.py","content":"def chronological(rows):
    return sorted(rows, key=lambda row: (int(row['t']), str(row['id'])))


def split(rows, cutoff, gap):
    try:
        valid_gap = gap >= 0
    except (TypeError, ValueError):
        raise ValueError('gap') from None
    if not valid_gap:
        raise ValueError('gap')

    rows = list(rows)
    bounds = {}
    for row in rows:
        entity = row['entity']
        timestamp = int(row['t'])
        if entity not in bounds:
            bounds[entity] = (timestamp, timestamp)
        else:
            earliest, latest = bounds[entity]
            bounds[entity] = (min(earliest, timestamp), max(latest, timestamp))

    labels = {}
    for entity, (earliest, latest) in bounds.items():
        if latest < cutoff - gap:
            labels[entity] = 'train'
        elif earliest >= cutoff + gap:
            labels[entity] = 'eval'
        else:
            labels[entity] = 'purged'

    result = {'train': [], 'eval': [], 'purged': []}
    for row in chronological(rows):
        result[labels[row['entity']]].append(row['id'])
    return result
